//go:build arm64

package floats

import "unsafe"

// The NEON kernel of CMulTo (cmulto.go), generated by go-asmgen (cmulto_arm64_gen.go)
// into cmulto_arm64.s: steps of four complex numbers (a complex128 is two adjacent
// float64, which VLD2 de-interleaves), the Go loop finishes the last ones. NEON is the
// ARMv8-A baseline: no gate. go:noescape.
//
//go:noescape
func cmulToNEON(dst, a, b *float64, steps int)

func cmulTo(dst, a, b []complex128) {
	q := len(dst) / 4
	if q > 0 {
		cmulToNEON(f64ptr(&dst[0]), f64ptr(&a[0]), f64ptr(&b[0]), q)
	}
	cmulToTail(dst, a, b, 4*q)
}

func f64ptr(p *complex128) *float64 { return (*float64)(unsafe.Pointer(p)) }
